style.css:
@-moz-document url-prefix("https://waterwaarden.nl/phpmyadmin/index.php?route=/sql&pos=0&db=thuisbatterij&table=ecoflow2") {
/* Zorg ervoor dat de kolommen in phpMyAdmin breed genoeg zijn om de inhoud weer te geven */
    table.data_table th, table.data_table td {
        width: auto !important; /* Zorgt ervoor dat de kolommen automatisch worden aangepast */
        max-width: none !important; /* Verwijder de maximale breedtebeperkingen */
        white-space: nowrap !important; /* Voorkom dat de tekst in kolommen wordt afgebroken */
        overflow: hidden !important; /* Zorg ervoor dat tekst niet buiten de cellen valt */
        text-overflow: ellipsis !important; /* Voeg een ellipsis toe als tekst te lang is */
    }

    /* Optioneel: Stel een minimale breedte in voor leesbaarheid */
    table.data_table th, table.data_table td {
        min-width: 120px !important; /* Pas de minimale breedte aan naar wens */
    }
}
